UPDATE merchant_goods
merchant_base_id = #{merchantId}, goods_name = #{goods.goodsName}, category = #{goods.category}, sub_category = #{goods.subCategory}, price = #{goods.price}, original_price = #{goods.originalPrice}, stock = #{goods.stock}, sales_count = #{goods.salesCount}, description = #{goods.description}, tag_codes = #{goods.tagCodes}, status = #{goods.status}, avg_rating = #{goods.avgRating}, rating_count = #{goods.ratingCount}, five_star_rate = #{goods.fiveStarRate}, four_star_rate = #{goods.fourStarRate}, three_star_rate = #{goods.threeStarRate}, two_star_rate = #{goods.twoStarRate}, one_star_rate = #{goods.oneStarRate}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET status = #{status}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET stock = #{stock}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET sales_count = sales_count + #{count}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET stock = stock - #{count}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId} AND stock >= #{count}

